const t={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:"पेस्ट करने के लिए तैयार Klipper कॉन्फ़िग ब्लॉक और मैक्रो - स्टार्ट सीक्वेंस, फ़िलामेंट हैंडलिंग, इनपुट शेपिंग, बेड मेश और बहुत कुछ। किसी एक को कॉपी करें और अपने printer.cfg में डालें (Config Editor इसे पेस्ट करने के लिए अच्छी जगह है)।"}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"सहायता"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"कॉन्फ़िग टेम्पलेट के बारे में"}},close:{t:0,b:{t:2,i:[{t:3}],s:"बंद करें"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"उपयोग कैसे करें"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"मैक्रो या कॉन्फ़िग ब्लॉक खोजने के लिए श्रेणी से फ़िल्टर करें।"}},{t:0,b:{t:2,i:[{t:3}],s:"विवरण पढ़ें और इसे किन सेक्शन की ज़रूरत है यह जानें।"}},{t:0,b:{t:2,i:[{t:3}],s:"टेम्पलेट कॉपी करें, इसे अपने कॉन्फ़िग में पेस्ट करें, और वैल्यू समायोजित करें।"}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:"ये क्या हैं"}},body:{t:0,b:{t:2,i:[{t:3}],s:"सामान्य Klipper बिल्डिंग ब्लॉक का एक चुना हुआ सेट: gcode_macros (PRINT_START, PAUSE/RESUME, फ़िलामेंट लोड/अनलोड, M600) और कॉन्फ़िग सेक्शन ([input_shaper], [bed_mesh], [firmware_retraction], …)। ये शुरुआती बिंदु हैं - हर एक को पढ़ें और अपनी मशीन के लिए ट्यून करें।"}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:"टेम्पलेट डालना"}},body:{t:0,b:{t:2,i:[{t:3}],s:"एक टेम्पलेट कॉपी करें, फिर इसे अपने printer.cfg में पेस्ट करें - Config Editor का Raw व्यू एक सुविधाजनक जगह है। सहेजने के बाद, फ़र्मवेयर रीस्टार्ट इसे लागू करता है। हमेशा पहले वैल्यू की समीक्षा करें; यहाँ के डिफ़ॉल्ट उचित हैं लेकिन आपके प्रिंटर के लिए ट्यून नहीं किए गए हैं।"}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:"आवश्यक सेक्शन"}},body:{t:0,b:{t:2,i:[{t:3}],s:"हर टेम्पलेट उन कॉन्फ़िग सेक्शन को सूचीबद्ध करता है जिन्हें वह परिभाषित करता है या जिन पर निर्भर करता है। अगर कोई सेक्शन आपके कॉन्फ़िग में पहले से मौजूद है, तो डुप्लिकेट पेस्ट करने के बजाय कीज़ को मर्ज करें (डुप्लिकेट सेक्शन स्टार्टअप पर अस्वीकार कर दिया जाता है)।"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"शब्दावली"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:"टेम्पलेट"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klipper कॉन्फ़िग या मैक्रो G-code का पेस्ट करने के लिए तैयार स्निपेट जिसे आप printer.cfg में कॉपी करते हैं।"}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:"gcode_macro"}},def:{t:0,b:{t:2,i:[{t:3}],s:"एक नामित कमांड जिसे आप कॉन्फ़िग में परिभाषित करते हैं (उदा. PRINT_START) जो G-code का एक सीक्वेंस चलाता है।"}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:"सेक्शन"}},def:{t:0,b:{t:2,i:[{t:3}],s:"एक [ब्रैकेट वाला] कॉन्फ़िग ब्लॉक, उदा. [bed_mesh] - वह इकाई जिसमें Klipper कॉन्फ़िगरेशन समूहित होता है।"}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:"श्रेणी"}},all:{t:0,b:{t:2,i:[{t:3}],s:"सभी श्रेणियाँ"}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:"कॉपी करें"}},copied:{t:0,b:{t:2,i:[{t:3}],s:"कॉपी हो गया!"}},requires:{t:0,b:{t:2,i:[{t:3,v:"सेक्शन: "},{t:4,k:"sections"}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:"-"}}},count:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" टेम्पलेट"}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:"टेम्पलेट लोड हो रहे हैं…"}},error:{t:0,b:{t:2,i:[{t:3}],s:"टेम्पलेट लोड नहीं हो सके।"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"इस श्रेणी में कोई टेम्पलेट नहीं है।"}},retry:{t:0,b:{t:2,i:[{t:3}],s:"पुनः प्रयास करें"}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:"कॉन्फ़िग ब्लॉक"}},macros:{t:0,b:{t:2,i:[{t:3}],s:"मैक्रो"}}}}};export{t as default};
